import { expect, it } from "vitest";
import { MemoryFileSystem } from "@poe-code/safe-fs/core";
import { runConvertCli, runConvertCliSync } from "./index.js";

// Independently generated by ImageMagick 7.1.2-35 Q16-HDRI from PPM pixels
// 208040ff2200 with -colorspace Lab (or sRGB), optional 37% alpha and -depth 16.
// Expected bytes come from reading that exact TXT with -colorspace sRGB -depth 8 rgba:-.
const fixtures = [
  {
    "name": "Lab 8-bit alpha=False",
    "text": "# ImageMagick pixel enumeration: 2,1,0,255,cielab\n0,0: (120,85,154)  #78559A  cielab(47.1249,-42.1867,26.9476)\n1,0: (139,204,195)  #8BCCC3  cielab(54.4516,76.5968,67.6603)\n",
    "rgba": "1d8041ffff2301ff",
    "space": "CIELab"
  },
  {
    "name": "Lab 8-bit alpha=True",
    "text": "# ImageMagick pixel enumeration: 2,1,0,255,cielaba\n0,0: (120,85,154,94)  #78559A5E  cielaba(47.1249,-42.1867,26.9476,0.370006)\n1,0: (139,204,195,94)  #8BCCC35E  cielaba(54.4516,76.5968,67.6603,0.370006)\n",
    "rgba": "1d80415eff23015e",
    "space": "CIELab"
  },
  {
    "name": "Lab 16-bit alpha=False",
    "text": "# ImageMagick pixel enumeration: 2,1,0,65535,cielab\n0,0: (30883,21926,39693)  #78A355A69B0D  cielab(47.1249,-42.1867,26.9476)\n1,0: (35685,52453,50156)  #8B65CCE5C3EC  cielab(54.4516,76.5968,67.6603)\n",
    "rgba": "208040ffff2200ff",
    "space": "CIELab"
  },
  {
    "name": "Lab 16-bit alpha=True",
    "text": "# ImageMagick pixel enumeration: 2,1,0,65535,cielaba\n0,0: (30883,21926,39693,24248)  #78A355A69B0D5EB8  cielaba(47.1249,-42.1867,26.9476,0.370006)\n1,0: (35685,52453,50156,24248)  #8B65CCE5C3EC5EB8  cielaba(54.4516,76.5968,67.6603,0.370006)\n",
    "rgba": "2080405eff22005e",
    "space": "CIELab"
  },
  {
    "name": "sRGB 8-bit alpha=False",
    "text": "# ImageMagick pixel enumeration: 2,1,0,255,srgb\n0,0: (32,128,64)  #208040  srgb(32,128,64)\n1,0: (255,34,0)  #FF2200  srgb(255,34,0)\n",
    "rgba": "208040ffff2200ff",
    "space": "sRGB"
  }
];

for (const mode of ["buffered", "retained", "sync"] as const) {
  it.each(fixtures)(`decodes native $name TXT samples via ${mode}`, async fixture => {
    const bytes = new TextEncoder().encode(fixture.text);
    const files = new Map([["/native.txt", bytes]]), filesystem = new MemoryFileSystem();
    await filesystem.writeFile("/native.txt", bytes);
    const run = (args: string[]) => mode === "sync" ? runConvertCliSync(args, files)
      : runConvertCli(args, mode === "retained" ? { filesystem, cwd: "/" } : files);
    expect(await run(["/native.txt", "-format", "%[colorspace]", "info:"])).toMatchObject({ exitCode: 0, stderr: "", stdout: fixture.space });
    expect(await run(["txt:/native.txt", "-colorspace", "sRGB", "-depth", "8", "rgba:/out"]))
      .toMatchObject({ exitCode: 0, stderr: "" });
    const output = mode === "retained" ? await filesystem.readFile("/out") as Uint8Array : files.get("/out")!;
    expect(Buffer.from(output).toString("hex")).toBe(fixture.rgba);
  });
}
